import{_ as t,o as n,c as i,a2 as r}from"./chunks/framework.vLhlLNVn.js";const g=JSON.parse('{"title":"Quellen, Einheiten und Vorzeichen","description":"","frontmatter":{"order":1,"adapter":"sourceanalytix","editLink":"https://github.com/DrozmotiX/ioBroker.sourceanalytix/edit/main/docs/de/02.anleitungen/01.quellen-und-einheiten.md"},"headers":[],"relativePath":"de/adapter/sourceanalytix/anleitungen/quellen-und-einheiten.md","filePath":"de/adapter/sourceanalytix/anleitungen/quellen-und-einheiten.md","lastUpdated":null}'),a={name:"de/adapter/sourceanalytix/anleitungen/quellen-und-einheiten.md"};function s(u,e,d,l,o,h){return n(),i("div",null,[...e[0]||(e[0]=[r('<h1 id="quellen-einheiten-und-vorzeichen" tabindex="-1">Quellen, Einheiten und Vorzeichen <a class="header-anchor" href="#quellen-einheiten-und-vorzeichen" aria-label="Permalink to &quot;Quellen, Einheiten und Vorzeichen&quot;">​</a></h1><p><a id="separate-import-feed-one-datapoint"></a></p><h2 id="wie-trenne-ich-bezug-und-einspeisung-ein-datenpunkt-mit-vorzeichen" tabindex="-1">Wie trenne ich Bezug und Einspeisung (ein Datenpunkt mit Vorzeichen)? <a class="header-anchor" href="#wie-trenne-ich-bezug-und-einspeisung-ein-datenpunkt-mit-vorzeichen" aria-label="Permalink to &quot;Wie trenne ich Bezug und Einspeisung (ein Datenpunkt mit Vorzeichen)?&quot;">​</a></h2><p><strong>Kurz:</strong> SourceAnalytix erkennt Bezug und Einspeisung nicht am Vorzeichen. Du legst zwei Quellen an: den Datenpunkt selbst für den Bezug und einen Alias mit umgedrehtem Vorzeichen für die Einspeisung. Beide bekommen „Negative Werte ignorieren&quot;, die Einspeisung zusätzlich eine Preisdefinition mit der Kostenart „Erträge&quot;.</p><p>Die Richtung einer Quelle kommt allein aus der Kostenart ihrer Preisdefinition. Bei „Kosten&quot; schreibt SourceAnalytix Verbrauch und Kosten (<code>consumed</code>, <code>costs</code>), bei „Erträge&quot; Lieferung und Erlöse (<code>delivered</code>, <code>earnings</code>). Ein negativer Leistungswert wird ohne Haken als negative Energie gezählt und senkt den Gesamtstand, denn Leistungsquellen haben keine Reset-Erkennung. Mit dem Haken „Negative Werte ignorieren&quot; zählt er als 0 W.</p><h3 id="so-gehst-du-vor-ab-v0-7-0" tabindex="-1">So gehst du vor (ab v0.7.0) <a class="header-anchor" href="#so-gehst-du-vor-ab-v0-7-0" aria-label="Permalink to &quot;So gehst du vor (ab v0.7.0)&quot;">​</a></h3><ol><li>Öffne die Instanz-Einstellungen von SourceAnalytix und lege im Tab „Preisdefinitionen&quot; zwei Zeilen an, zum Beispiel <code>Strom Bezug</code> mit Kostenart „Kosten&quot; und <code>Einspeisung</code> mit Kostenart „Erträge&quot;, beide mit der Einheit <code>kWh</code>. Bei der Einspeisung ist der „Preis pro Einheit&quot; deine Einspeisevergütung je kWh. Speichern startet den Adapter neu.</li><li>Lege unter „Objekte&quot; einen Alias auf deinen Leistungs-Datenpunkt an, der beim Lesen das Vorzeichen umdreht (<code>-val</code>), und gib ihm die Einheit <code>W</code>.</li><li>Wechsle in den Instanz-Einstellungen in den Tab „Übersicht&quot; und klicke auf „Quelle hinzufügen&quot;. Wähle den Original-Datenpunkt, die Messart „Leistung&quot; und den Preis <code>Strom Bezug</code>. Setze im Schritt „Berechnung&quot; unter „Für Experten&quot; den Haken „Negative Werte ignorieren&quot; und aktiviere die Quelle.</li><li>Lege genauso eine zweite Quelle für den Alias an, mit dem Preis <code>Einspeisung</code> und ebenfalls „Negative Werte ignorieren&quot;.</li><li>Der Bezug steht danach unter <code>sourceanalytix.0.&lt;Bezug&gt;.currentYear.consumed</code>, die Einspeisung unter <code>sourceanalytix.0.&lt;Einspeisung&gt;.currentYear.delivered</code> und ihre Erlöse unter <code>…currentYear.earnings</code>.</li></ol><p>Bei einer Quelle, die schon läuft, setzt du den Haken in ihrer Detailansicht unter „Einstellungen&quot; und klickst auf „⚡ Übernehmen&quot;. Das wirkt sofort, ohne Neustart.</p><div class="warning custom-block github-alert"><p class="custom-block-title">WARNING</p><p>Ohne „Negative Werte ignorieren&quot; zieht die Einspeisung den Gesamtstand des Bezugs wieder herunter. Der Tagesverbrauch zeigt dann nur den Saldo und kann negativ werden.</p></div><p>Liefert dein Stromzähler zwei eigene Zählerstände für Bezug und Einspeisung, nimm lieber diese als zwei Quellen vom Typ Zählerstand. Das ist genauer als die Leistung, und ein Zählerstand mit Vorzeichen kommt dabei nicht vor: Fällt ein Zählerstand, behandelt SourceAnalytix das als Reset und nicht als Einspeisung. Warum der Zählerstand genauer ist, steht unter <a href="./../erste-schritte/erster-zaehler#datapoint-enable-meter-kwh-power">Zähler (kWh) oder Leistung (W)?</a>.</p><p>Eine eigene Einstellung, die Bezug und Einspeisung aus einem Datenpunkt trennt, ist geplant (<a href="https://github.com/DrozmotiX/ioBroker.sourceanalytix/issues/1272" target="_blank" rel="noreferrer">#1272</a>).</p><p><strong>Bis v0.6.x:</strong> Den Haken „Negative Leistungswerte ignorieren&quot; findest du in den SourceAnalytix-Einstellungen am Datenpunkt (Objekte, Schraubenschlüssel) unter „Berechnungseinstellungen&quot;.</p><p><strong>Siehe auch:</strong> <a href="#track-pv-yield-feed-earnings">Wie erfasse ich PV-Ertrag, Einspeisung und Erlöse?</a> · <a href="#sourceanalytix-compute-consumption-meter-reading">Kann SourceAnalytix aus Leistung Verbrauch berechnen?</a> · <a href="./preise-und-kosten#assign-prices-create-custom-tariffs">Wie ordne ich Preise zu?</a></p><p><a id="unit-datapoint-kwh-wh-m3"></a></p><h2 id="welche-einheit-stelle-ich-am-datenpunkt-ein-kwh-statt-wh-m3-statt-liter" tabindex="-1">Welche Einheit stelle ich am Datenpunkt ein (kWh statt Wh, m³ statt Liter)? <a class="header-anchor" href="#welche-einheit-stelle-ich-am-datenpunkt-ein-kwh-statt-wh-m3-statt-liter" aria-label="Permalink to &quot;Welche Einheit stelle ich am Datenpunkt ein (kWh statt Wh, m³ statt Liter)?&quot;">​</a></h2><p><strong>Kurz:</strong> An der Quelle stellst du die Einheit ein, in der der Datenpunkt wirklich liefert, meist reicht „Automatisch erkennen&quot;. Die Einheit, in der du die Werte siehst, kommt aus der Preisdefinition. Von Wh nach kWh oder von l nach m³ rechnet SourceAnalytix selbst um.</p><p>Beide Einheiten und alle Umrechnungen stehen in der Tabelle unter <a href="./../referenz/einstellungen#units-supported-energy-volume-weight">Welche Einheiten werden unterstützt?</a>.</p><h3 id="so-gehst-du-vor-ab-v0-7-0-1" tabindex="-1">So gehst du vor (ab v0.7.0) <a class="header-anchor" href="#so-gehst-du-vor-ab-v0-7-0-1" aria-label="Permalink to &quot;So gehst du vor (ab v0.7.0)&quot;">​</a></h3><ol><li>Beim Anlegen zeigt der Assistent im Schritt „Einheit&quot; die Zeile „Erkannt aus dem Datenpunkt: …&quot;. Wähle die Einheit, in der der Datenpunkt zählt. Stimmt die erkannte Einheit, lass sie stehen.</li><li>Im Schritt „Preis&quot; kannst du nur Preisdefinitionen wählen, deren Einheit dazu passt. Die anderen sind ausgegraut und tragen den Hinweis „andere Einheit&quot;.</li><li>Bei einer bestehenden Quelle änderst du die Einheit in ihrer Detailansicht unter „Einstellungen&quot; im Feld „Einheit&quot; und klickst auf „⚡ Übernehmen&quot;.</li><li>Erkennt SourceAnalytix keine Einheit, steht im Tab „Probleme&quot; „Einheit fehlt oder wird nicht erkannt&quot;. Mit „Beheben&quot; wählst du sie direkt aus.</li></ol><p>Typische Fehler:</p><ul><li><strong>Zählerstand, aber als <code>W</code> beschriftet:</strong> SourceAnalytix hält den Wert für eine Leistung und summiert ihn über die Zeit auf. Es entstehen absurd hohe Werte. Wähle <code>Wh</code> oder <code>kWh</code>.</li><li><strong>Leistung, aber als <code>Wh</code> oder <code>kWh</code> beschriftet:</strong> SourceAnalytix hält jeden Wert für einen Zählerstand. Wähle <code>W</code> oder <code>kW</code>.</li><li><strong><code>Wh</code> und <code>kWh</code> verwechselt:</strong> Alle Werte sind um den Faktor 1.000 zu hoch oder zu niedrig.</li></ul><h3 id="warum-kwh-statt-m3-erscheint" tabindex="-1">Warum kWh statt m³ erscheint <a class="header-anchor" href="#warum-kwh-statt-m3-erscheint" aria-label="Permalink to &quot;Warum kWh statt m³ erscheint&quot;">​</a></h3><p>SourceAnalytix zeigt alle Werte in der Einheit der Preisdefinition. Siehst du kWh, obwohl dein Gaszähler m³ liefert, hat die gewählte Preisdefinition die Einheit <code>kWh</code>. Lege für Gas eine eigene Preisdefinition mit der Einheit <code>m³</code> und dem Preis je m³ an und wähle sie bei der Quelle. Liter und Kubikmeter rechnet SourceAnalytix ineinander um, m³ Gas in kWh dagegen nicht. Ab v0.6.2 startet eine Quelle mit <code>m³</code> und einer Preisdefinition in <code>kWh</code> gar nicht, im Log steht dann <code>Unit m³ of &lt;Datenpunkt&gt; cannot be converted to unit kWh of price definition &lt;Name&gt;</code>.</p><p>Eine Umrechnung von m³ Gas in kWh ist geplant (<a href="https://github.com/DrozmotiX/ioBroker.sourceanalytix/issues/6" target="_blank" rel="noreferrer">#6</a>).</p><h3 id="wenn-du-die-einheit-nachtraglich-anderst" tabindex="-1">Wenn du die Einheit nachträglich änderst <a class="header-anchor" href="#wenn-du-die-einheit-nachtraglich-anderst" aria-label="Permalink to &quot;Wenn du die Einheit nachträglich änderst&quot;">​</a></h3><p>Eine neue Einheit an der Quelle oder in der Preisdefinition gilt ab dem nächsten Wert. Was schon gespeichert ist, rechnet SourceAnalytix nicht um: den Gesamtstand, die Startwerte und die Werte der laufenden und vergangenen Perioden. War die Einheit vorher falsch, stimmen Gesamtstand und Verbrauch deshalb auch nach der Änderung nicht. Korrigiere sie danach mit „Zählerstand angleichen&quot; und repariere die Kosten, wie unter <a href="./zaehlerstaende-korrigieren#correct-wrong-too-high-negative">Falsche Werte korrigieren</a> beschrieben.</p><p><strong>Bis v0.6.x:</strong> Die Einheit stellst du in den SourceAnalytix-Einstellungen am Datenpunkt unter „Wählen Sie Einheit&quot; ein, Voreinstellung ist „Automatisch erkennen&quot;. Wie du dorthin kommst, steht unter <a href="./../erste-schritte/erster-zaehler#configure-sourceanalytix-datapoint">Wo konfiguriere ich SourceAnalytix?</a>.</p><p><strong>Siehe auch:</strong> <a href="./../erste-schritte/erster-zaehler#start-values-unit">Startwerte und ihre Einheit</a> · <a href="./../fehlerbehebung/log-meldungen#error-unit-not-supported-no">Fehler „unit not supported&quot; / „No unit defined&quot;</a></p><p><a id="sourceanalytix-compute-consumption-meter-reading"></a></p><h2 id="kann-sourceanalytix-aus-leistung-w-verbrauch-und-zahlerstand-berechnen" tabindex="-1">Kann SourceAnalytix aus Leistung (W) Verbrauch und Zählerstand berechnen? <a class="header-anchor" href="#kann-sourceanalytix-aus-leistung-w-verbrauch-und-zahlerstand-berechnen" aria-label="Permalink to &quot;Kann SourceAnalytix aus Leistung (W) Verbrauch und Zählerstand berechnen?&quot;">​</a></h2><p><strong>Kurz:</strong> Ja. SourceAnalytix multipliziert jeden Leistungswert mit der Zeit bis zum nächsten Wert und addiert das Ergebnis zu einem eigenen Gesamtstand. Daraus entstehen Verbrauch und Kosten für Tag, Woche, Monat, Quartal und Jahr, in der Energie-Einheit der Preisdefinition, zum Beispiel kWh.</p><p>Der Gesamtstand (<code>sourceanalytix.0.&lt;Gerät&gt;.cumulativeReading</code>) beginnt bei der Aktivierung bei 0. Er zeigt also die Energie seit der Aktivierung, nicht den Stand deines Stromzählers. Wie genau er ist, hängt davon ab, wie oft das Gerät sendet. Der erste Wert nach der Aktivierung und nach jedem Neustart von SourceAnalytix dient nur als Ausgangspunkt. Eine Reset-Erkennung gibt es für Leistungsquellen nicht, und Startwerte brauchst du keine.</p><h3 id="so-gehst-du-vor-ab-v0-7-0-2" tabindex="-1">So gehst du vor (ab v0.7.0) <a class="header-anchor" href="#so-gehst-du-vor-ab-v0-7-0-2" aria-label="Permalink to &quot;So gehst du vor (ab v0.7.0)&quot;">​</a></h3><ol><li>Klicke in den Instanz-Einstellungen im Tab „Übersicht&quot; auf „Quelle hinzufügen&quot; und wähle den Datenpunkt mit der Leistung.</li><li>Wähle im Schritt „Messart&quot; „Leistung&quot;. Bei den Einheiten <code>W</code> und <code>kW</code> schlägt der Assistent das schon vor.</li><li>Wähle im Schritt „Preis&quot; eine Preisdefinition mit <code>Wh</code>, <code>kWh</code> oder <code>MWh</code>. Andere Einheiten sind ausgegraut.</li><li>Unter „Für Experten&quot; im Schritt „Berechnung&quot; findest du „Mittelwert bei Leistung&quot; und „Negative Werte ignorieren&quot;. Was sie bewirken, steht unter <a href="./../erste-schritte/erster-zaehler#datapoint-enable-meter-kwh-power">Wenn du nur einen Leistungswert hast</a>.</li><li>Im Schritt „Startwerte&quot; ist nur „Ab jetzt zählen&quot; möglich. Gib einen Namen ein und aktiviere die Quelle.</li></ol><p>Willst du den Gesamtstand trotzdem an einen echten Zähler anlehnen, nimm die Aktion „Zählerstand angleichen&quot;. Sie setzt den Gesamtstand, die Werte der laufenden Perioden bleiben gleich. Weil die Leistung nur eine Schätzung ist, laufen beide danach wieder auseinander. Die Aktion „Zähler getauscht&quot; gibt es bei Leistungsquellen nicht.</p><div class="tip custom-block github-alert"><p class="custom-block-title">TIP</p><p>Fällt das Gerät oder das WLAN aus, rechnet SourceAnalytix den letzten Wert über die ganze Pause hoch. Das verhinderst du mit „Maximale Lücke zwischen Leistungswerten (Minuten)&quot; in der Detailansicht der Quelle unter „Einstellungen&quot; (ab v0.7.0). Meldet eine Leistungsquelle lange keinen Wert, zeigt der Tab „Probleme&quot; „Leistungsquelle meldet seit langem keinen Wert&quot;.</p></div><p><strong>Siehe auch:</strong> <a href="./../hintergrund/berechnung#sourceanalytix-convert-watts-kwh">Wie rechnet SourceAnalytix Watt in kWh um?</a> · <a href="./../erste-schritte/erster-zaehler#datapoint-enable-meter-kwh-power">Zähler (kWh) oder Leistung (W)?</a> · <a href="./../referenz/einstellungen#source-types-exist-meter-power">Welche Quelltypen gibt es?</a></p><p><a id="track-pv-yield-feed-earnings"></a></p><h2 id="wie-erfasse-ich-pv-ertrag-einspeisung-und-erlose" tabindex="-1">Wie erfasse ich PV-Ertrag, Einspeisung und Erlöse? <a class="header-anchor" href="#wie-erfasse-ich-pv-ertrag-einspeisung-und-erlose" aria-label="Permalink to &quot;Wie erfasse ich PV-Ertrag, Einspeisung und Erlöse?&quot;">​</a></h2><p><strong>Kurz:</strong> Jeder Zähler wird eine eigene Quelle: der Gesamtertrag des Wechselrichters und der Einspeisezähler. Nimm jeweils den Zählerstand in kWh, der nur steigt, und eine Preisdefinition mit der Kostenart „Erträge&quot;. Dann schreibt SourceAnalytix Lieferung und Erlöse statt Verbrauch und Kosten.</p><table tabindex="0"><thead><tr><th>Was du erfassen willst</th><th>Datenpunkt</th><th>Preisdefinition</th></tr></thead><tbody><tr><td>PV-Ertrag</td><td>Gesamtertrag des Wechselrichters in kWh</td><td>Kostenart „Erträge&quot;. Willst du kein Geld sehen, lass bei der Quelle „Kosten&quot; aus.</td></tr><tr><td>Einspeisung und Erlöse</td><td>Einspeisezähler deines Stromzählers</td><td>Kostenart „Erträge&quot;, „Preis pro Einheit&quot; = Einspeisevergütung je kWh</td></tr><tr><td>Netzbezug</td><td>Bezugszähler deines Stromzählers</td><td>Kostenart „Kosten&quot;</td></tr></tbody></table><p>Die Werte stehen danach unter <code>sourceanalytix.0.&lt;Gerät&gt;.currentYear.delivered</code>, die Erlöse unter <code>…currentYear.earnings</code>. In der Detailansicht der Quelle heißen die Spalten „Einspeisung&quot; und „Erlös&quot;.</p><h3 id="so-gehst-du-vor-ab-v0-7-0-3" tabindex="-1">So gehst du vor (ab v0.7.0) <a class="header-anchor" href="#so-gehst-du-vor-ab-v0-7-0-3" aria-label="Permalink to &quot;So gehst du vor (ab v0.7.0)&quot;">​</a></h3><ol><li>Lege im Tab „Preisdefinitionen&quot; eine Zeile mit Kostenart „Erträge&quot; und Einheit <code>kWh</code> an. Speichern startet den Adapter neu.</li><li>Klicke im Tab „Übersicht&quot; auf „Quelle hinzufügen&quot; und wähle den Gesamtzähler. Datenpunkte, die nach einem Tageswert aussehen („heute&quot;, „today&quot;, „daily&quot;), markiert der Assistent mit „Tageszähler&quot;.</li><li>Wähle die Messart „Zählerstand&quot; und im Schritt „Preis&quot; die neue Preisdefinition.</li><li>Im Schritt „Startwerte&quot; ist „Ab jetzt zählen&quot; richtig, wenn die Perioden ab heute zählen sollen. Soll der Ertrag seit Beginn des Tages oder Monats mitzählen, wähle „Verbrauch seit Periodenbeginn mitzählen&quot; und trage die Zählerstände zum Periodenbeginn ein. Wie, steht unter <a href="./../erste-schritte/erster-zaehler#start-values-unit">Was trage ich bei den Startwerten ein?</a>.</li><li>Gib einen Namen ein und aktiviere die Quelle. Für den Einspeisezähler wiederholst du die Schritte.</li></ol><div class="important custom-block github-alert"><p class="custom-block-title">IMPORTANT</p><p>Nimm nicht „Ertrag heute&quot; oder einen ähnlichen Tageszähler. Er springt jede Nacht auf 0. Das klappt nur mit Reset-Erkennung, und bei jedem Sprung fehlt ein kleiner Teil des Ertrags. Mehr dazu unter <a href="./../hintergrund/zaehler-reset#counter-reset-0-daily-happens">Zähler, der täglich auf 0 zurückgesetzt wird</a>.</p></div><p>Liefert dein Wechselrichter nur die momentane Leistung, nimm sie als Leistungsquelle, siehe <a href="#sourceanalytix-compute-consumption-meter-reading">Kann SourceAnalytix aus Leistung Verbrauch berechnen?</a>. Hast du nur einen Netz-Datenpunkt mit Vorzeichen, steht unter <a href="#separate-import-feed-one-datapoint">Bezug und Einspeisung trennen</a>, wie du daraus zwei Quellen machst.</p><p>Eigenverbrauch und Autarkie berechnet SourceAnalytix nicht. Das ist geplant (<a href="https://github.com/DrozmotiX/ioBroker.sourceanalytix/issues/643" target="_blank" rel="noreferrer">#643</a>).</p><p><strong>Bis v0.6.x:</strong> Du aktivierst die Datenpunkte einzeln in den SourceAnalytix-Einstellungen am Datenpunkt und wählst dort die Preisdefinition, siehe <a href="./../erste-schritte/erster-zaehler#configure-sourceanalytix-datapoint">Wo konfiguriere ich SourceAnalytix?</a>.</p><p><strong>Siehe auch:</strong> <a href="./preise-und-kosten#assign-prices-create-custom-tariffs">Wie ordne ich Preise zu?</a> · <a href="./../erste-schritte/erster-zaehler#values-consumption-today-yesterday">Wo finde ich meine Werte?</a></p><p><a id="derive-counter-flow-run-time"></a></p><h2 id="wie-leite-ich-einen-zahler-aus-durchfluss-laufzeit-oder-mehreren-geraten-ab" tabindex="-1">Wie leite ich einen Zähler aus Durchfluss, Laufzeit oder mehreren Geräten ab? <a class="header-anchor" href="#wie-leite-ich-einen-zahler-aus-durchfluss-laufzeit-oder-mehreren-geraten-ab" aria-label="Permalink to &quot;Wie leite ich einen Zähler aus Durchfluss, Laufzeit oder mehreren Geräten ab?&quot;">​</a></h2><p><strong>Kurz:</strong> Mit einem Skript. SourceAnalytix wertet jeden Datenpunkt einzeln aus und summiert über die Zeit nur Leistung (W) und Impulse pro Minute auf. Für Summen, Durchfluss, Laufzeit oder Füllstand schreibst du deshalb per Skript einen eigenen Zählerstand, der nur steigt, in einer unterstützten Einheit und aktivierst diesen Datenpunkt.</p><table tabindex="0"><thead><tr><th>Fall</th><th>Was du tust</th></tr></thead><tbody><tr><td>Mehrere Phasen eines Zählers</td><td>Nimm den Gesamtzähler des Geräts. Gibt es keinen, bilde per Skript die Summe der Phasen-Zählerstände in kWh.</td></tr><tr><td>Mehrere Geräte zusammen</td><td>Jedes Gerät ist eine eigene Quelle. Brauchst du die Summe als Zähler, bilde sie per Skript.</td></tr><tr><td>Durchfluss (<code>m³/h</code>, <code>l/min</code>)</td><td>Raten werden nicht unterstützt. Das Skript addiert Rate × Zeit zu einem Volumen in <code>m³</code> oder <code>l</code>.</td></tr><tr><td>Brennerlaufzeit</td><td>Zeit wird nicht unterstützt. Das Skript rechnet Laufzeit × Verbrauch pro Stunde in <code>l</code> oder <code>kWh</code>.</td></tr><tr><td>Brennerstarts</td><td>Ab v0.7.0 direkt als Zählerstand mit der Einheit <code>piece</code>, siehe <a href="./../referenz/einstellungen#units-supported-energy-volume-weight">Stück und Impulse</a>.</td></tr><tr><td>Füllstand (z. B. Öltank)</td><td>Den Füllstand selbst nicht verwenden, er fällt beim Verbrauch. Das Skript summiert nur die Abnahmen auf und lässt das Nachtanken weg.</td></tr></tbody></table><p>Eine „Summe über alle Quellen&quot; ist geplant (<a href="https://github.com/DrozmotiX/ioBroker.sourceanalytix/issues/60" target="_blank" rel="noreferrer">#60</a>).</p><p>Wie du den Skript-Datenpunkt anlegst, damit SourceAnalytix ihn findet, steht im nächsten Abschnitt unter <a href="#use-script-datapoints-unreliable-sources">Skript-Datenpunkte</a>.</p><h3 id="reset-erkennung-fur-summen" tabindex="-1">Reset-Erkennung für Summen <a class="header-anchor" href="#reset-erkennung-fur-summen" aria-label="Permalink to &quot;Reset-Erkennung für Summen&quot;">​</a></h3><p>Eine Summe ist für SourceAnalytix ein gewöhnlicher Zählerstand. Wird ein Teilzähler zurückgesetzt, fällt die Summe. Mit eingeschalteter Reset-Erkennung behandelt SourceAnalytix das wie jeden Reset: Es wartet auf den nächsten Wert und zählt dann auf den alten Gesamtstand weiter. Wie das abläuft, steht unter <a href="./../hintergrund/zaehler-reset#device-reset-detected-mean-reset">Was bedeutet „Device reset detected&quot;?</a>.</p><div class="tip custom-block github-alert"><p class="custom-block-title">TIP</p><p>Am saubersten ist eine Summe, die gar nicht fällt: Das Skript addiert von jedem Teilzähler nur den Zuwachs seit dem letzten Wert und ignoriert Rückgänge. Dann bemerkt SourceAnalytix den Reset eines Teilzählers gar nicht.</p></div><p><strong>Siehe auch:</strong> <a href="./../referenz/einstellungen#units-supported-energy-volume-weight">Welche Einheiten werden unterstützt?</a> · <a href="#sourceanalytix-compute-consumption-meter-reading">Kann SourceAnalytix aus Leistung Verbrauch berechnen?</a></p><p><a id="use-script-datapoints-unreliable-sources"></a></p><h2 id="kann-ich-skript-datenpunkte-oder-unzuverlassige-quellen-verwenden" tabindex="-1">Kann ich Skript-Datenpunkte oder unzuverlässige Quellen verwenden? <a class="header-anchor" href="#kann-ich-skript-datenpunkte-oder-unzuverlassige-quellen-verwenden" aria-label="Permalink to &quot;Kann ich Skript-Datenpunkte oder unzuverlässige Quellen verwenden?&quot;">​</a></h2><p><strong>Kurz:</strong> Ja. Jeder Datenpunkt kann Quelle sein, egal ob ein Adapter, ein Skript, ein Alias oder die Simple-API ihn schreibt. Er muss nur eine Zahl in einer unterstützten Einheit liefern. Ob der Wert mit oder ohne Bestätigung (<code>ack</code>) geschrieben wurde, spielt keine Rolle.</p><p>Werte von einer anderen ioBroker-Installation müssen zuerst auf dem System mit SourceAnalytix als Datenpunkt ankommen, zum Beispiel über die Simple-API oder ein Skript.</p><h3 id="skript-datenpunkte" tabindex="-1">Skript-Datenpunkte <a class="header-anchor" href="#skript-datenpunkte" aria-label="Permalink to &quot;Skript-Datenpunkte&quot;">​</a></h3><ul><li>Lege den Datenpunkt mit dem Typ Zahl und der Einheit im Objekt an, zum Beispiel <code>kWh</code>. Nur Datenpunkte mit einer erkannten Einheit zeigt der Assistent unter „Passende Datenpunkte&quot;. Ohne Einheit wählst du den Datenpunkt über „Objekt auswählen&quot; und die Einheit im nächsten Schritt.</li><li>Schreibe einen Zählerstand, der nur steigt, und setze ihn nicht täglich auf 0.</li><li>Ab v0.6.2 liest SourceAnalytix auch Zählerstände, die als Text kommen, etwa <code>&quot;12,5&quot;</code>, ab v0.7.0 auch Leistungswerte wie <code>&quot;1,5&quot;</code> (<a href="https://github.com/DrozmotiX/ioBroker.sourceanalytix/issues/1288" target="_blank" rel="noreferrer">#1288</a>). Ist der Text keine Zahl, steht im Log <code>Value &quot;…&quot; of &lt;Datenpunkt&gt; is not a number, reading ignored</code>. Der Tab „Probleme&quot; meldet dann „Datenpunkt liefert Text statt einer Zahl&quot;.</li></ul><h3 id="ausreißer-und-nachkommastellen" tabindex="-1">Ausreißer und Nachkommastellen <a class="header-anchor" href="#ausreißer-und-nachkommastellen" aria-label="Permalink to &quot;Ausreißer und Nachkommastellen&quot;">​</a></h3><p>SourceAnalytix filtert Werte nur über die Reset-Erkennung:</p><ul><li>Ein Rückgang bis zur „Schwelle&quot; gilt als Messschwankung und wird ignoriert.</li><li>Ein einzelner tiefer Wert, etwa eine kurze 0, wird als Ausreißer verworfen, wenn der nächste Wert wieder beim alten Stand liegt.</li><li>Ein Sprung nach oben wird sofort als Verbrauch übernommen. Dagegen gibt es keinen Filter.</li></ul><p>Liefert deine Quelle manchmal unsinnig hohe Werte, filtere sie vorher mit einem Skript, das nur plausible, nicht fallende Werte in einen eigenen Datenpunkt schreibt, und aktiviere diesen. Ist ein falscher Wert schon übernommen, korrigierst du ihn wie unter <a href="./zaehlerstaende-korrigieren#correct-wrong-too-high-negative">Falsche Werte korrigieren</a>.</p><p>Viele Nachkommastellen in der Quelle stören nicht. Wie viele SourceAnalytix ausgibt, stellst du bei der Quelle unter „Für Experten&quot; mit „Nachkommastellen Verbrauch&quot; und „Nachkommastellen Kosten&quot; ein.</p><p><strong>Bis v0.6.1:</strong> Datenpunkte, die Zahlen als Text liefern, rechnet SourceAnalytix nicht. Ab v0.6.2 liest es sie (<a href="https://github.com/DrozmotiX/ioBroker.sourceanalytix/issues/1255" target="_blank" rel="noreferrer">#1255</a>).</p><p><strong>Siehe auch:</strong> <a href="./../hintergrund/zaehler-reset#device-reset-detected-mean-reset">Was bedeutet „Device reset detected&quot;?</a> · <a href="./../fehlerbehebung/falsche-werte-und-bekannte-fehler#so-many-decimals">So viele Nachkommastellen</a> · <a href="./../fehlerbehebung/log-meldungen#source-delivers-text-instead-number">Text statt Zahl</a></p>',72)])])}const m=t(a,[["render",s]]);export{g as __pageData,m as default};
